-- =====================================================================
--  Distribuidora La Mundial - version PostgreSQL / Supabase
--  01_tablas.sql : tablas, llaves y restricciones
--  Equivale a sql/01_creacion_tablas.sql (MySQL). Diferencias:
--   * AUTO_INCREMENT  -> GENERATED BY DEFAULT AS IDENTITY
--   * TINYINT(1)      -> BOOLEAN ;  DATETIME -> TIMESTAMPTZ
--   * Se trabaja en el esquema public (el que expone Supabase)
-- =====================================================================

-- Fecha y hora de Chile (el servidor de Supabase trabaja en UTC)
CREATE OR REPLACE FUNCTION fn_hoy() RETURNS date
LANGUAGE sql STABLE SET search_path = '' AS
$$ SELECT (now() AT TIME ZONE 'America/Santiago')::date $$;

CREATE OR REPLACE FUNCTION fn_hora() RETURNS time
LANGUAGE sql STABLE SET search_path = '' AS
$$ SELECT (now() AT TIME ZONE 'America/Santiago')::time(0) $$;

CREATE TABLE categoria (
    id_categoria INT GENERATED BY DEFAULT AS IDENTITY,
    nombre       VARCHAR(15) NOT NULL,
    CONSTRAINT pk_categoria PRIMARY KEY (id_categoria),
    CONSTRAINT uk_categoria_nombre UNIQUE (nombre)                 -- LS
);

CREATE TABLE marca (
    id_marca INT GENERATED BY DEFAULT AS IDENTITY,
    nombre   VARCHAR(20) NOT NULL,
    CONSTRAINT pk_marca PRIMARY KEY (id_marca),
    CONSTRAINT uk_marca_nombre UNIQUE (nombre)                     -- LS
);

CREATE TABLE proveedor (
    id_proveedor INT GENERATED BY DEFAULT AS IDENTITY,
    rut          VARCHAR(10)  NOT NULL,
    razon_social VARCHAR(100) NOT NULL,
    telefono     CHAR(9),
    email        VARCHAR(100),
    CONSTRAINT pk_proveedor PRIMARY KEY (id_proveedor),
    CONSTRAINT uk_proveedor_rut UNIQUE (rut),                      -- LS
    CONSTRAINT uk_proveedor_razon UNIQUE (razon_social)            -- LS
);

CREATE TABLE producto (
    id_producto  INT GENERATED BY DEFAULT AS IDENTITY,
    sku          VARCHAR(20)  NOT NULL,
    nombre       VARCHAR(100) NOT NULL,
    precio_det   INT NOT NULL,
    precio_may   INT NOT NULL,
    id_categoria INT NOT NULL,
    id_marca     INT NOT NULL,
    id_proveedor INT NOT NULL,
    CONSTRAINT pk_producto PRIMARY KEY (id_producto),
    CONSTRAINT uk_producto_sku UNIQUE (sku),                       -- LS
    CONSTRAINT fk_producto_categoria FOREIGN KEY (id_categoria) REFERENCES categoria (id_categoria),
    CONSTRAINT fk_producto_marca     FOREIGN KEY (id_marca)     REFERENCES marca (id_marca),
    CONSTRAINT fk_producto_proveedor FOREIGN KEY (id_proveedor) REFERENCES proveedor (id_proveedor),
    CONSTRAINT ck_producto_precios CHECK (precio_det > 0 AND precio_may > 0 AND precio_may <= precio_det)
);

CREATE TABLE stock (
    id_stock    INT GENERATED BY DEFAULT AS IDENTITY,
    id_producto INT  NOT NULL,
    cantidad    INT  NOT NULL DEFAULT 0,
    stock_min   INT  NOT NULL DEFAULT 0,
    fecha_act   DATE NOT NULL,
    CONSTRAINT pk_stock PRIMARY KEY (id_stock),
    CONSTRAINT uk_stock_producto UNIQUE (id_producto),             -- LS (1:1)
    CONSTRAINT fk_stock_producto FOREIGN KEY (id_producto) REFERENCES producto (id_producto) ON DELETE CASCADE,
    CONSTRAINT ck_stock_cantidad CHECK (cantidad >= 0 AND stock_min >= 0)
);

CREATE TABLE tipo_cliente (
    id_tipo_cliente   INT GENERATED BY DEFAULT AS IDENTITY,
    nombre            VARCHAR(20) NOT NULL,
    aplica_precio_may BOOLEAN NOT NULL DEFAULT false,
    CONSTRAINT pk_tipo_cliente PRIMARY KEY (id_tipo_cliente),
    CONSTRAINT uk_tipo_cliente_nombre UNIQUE (nombre)              -- LS
);

CREATE TABLE cliente (
    id_cliente      INT GENERATED BY DEFAULT AS IDENTITY,
    rut             VARCHAR(10)  NOT NULL,
    nombre          VARCHAR(100) NOT NULL,
    telefono        CHAR(9),
    id_tipo_cliente INT NOT NULL,
    CONSTRAINT pk_cliente PRIMARY KEY (id_cliente),
    CONSTRAINT uk_cliente_rut UNIQUE (rut),                        -- LS
    CONSTRAINT fk_cliente_tipo FOREIGN KEY (id_tipo_cliente) REFERENCES tipo_cliente (id_tipo_cliente)
);

CREATE TABLE empleado (
    id_empleado INT GENERATED BY DEFAULT AS IDENTITY,
    rut         VARCHAR(10)  NOT NULL,
    nombre      VARCHAR(100) NOT NULL,
    cargo       VARCHAR(30)  NOT NULL,
    CONSTRAINT pk_empleado PRIMARY KEY (id_empleado),
    CONSTRAINT uk_empleado_rut UNIQUE (rut)                        -- LS
);

CREATE TABLE ticket (
    id_ticket INT GENERATED BY DEFAULT AS IDENTITY,
    numero    INT         NOT NULL,
    fecha     DATE        NOT NULL,
    hora      TIME(0)     NOT NULL,
    estado    VARCHAR(15) NOT NULL DEFAULT 'emitido',
    CONSTRAINT pk_ticket PRIMARY KEY (id_ticket),
    CONSTRAINT ck_ticket_estado CHECK (estado IN ('emitido', 'atendido', 'anulado'))
);

CREATE TABLE venta (
    id_venta    INT GENERATED BY DEFAULT AS IDENTITY,
    fecha       DATE    NOT NULL,
    hora        TIME(0) NOT NULL,
    id_ticket   INT     NOT NULL,
    id_cliente  INT     NOT NULL,
    id_empleado INT     NOT NULL,
    CONSTRAINT pk_venta PRIMARY KEY (id_venta),
    CONSTRAINT uk_venta_ticket UNIQUE (id_ticket),                 -- LS (1:1)
    CONSTRAINT fk_venta_ticket   FOREIGN KEY (id_ticket)   REFERENCES ticket (id_ticket),
    CONSTRAINT fk_venta_cliente  FOREIGN KEY (id_cliente)  REFERENCES cliente (id_cliente),
    CONSTRAINT fk_venta_empleado FOREIGN KEY (id_empleado) REFERENCES empleado (id_empleado)
);

CREATE TABLE detalle_venta (
    id_detalle  INT GENERATED BY DEFAULT AS IDENTITY,
    id_venta    INT NOT NULL,
    id_producto INT NOT NULL,
    cantidad    INT NOT NULL,
    precio_unit INT NOT NULL,
    CONSTRAINT pk_detalle_venta PRIMARY KEY (id_detalle),
    CONSTRAINT fk_detalle_venta    FOREIGN KEY (id_venta)    REFERENCES venta (id_venta) ON DELETE CASCADE,
    CONSTRAINT fk_detalle_producto FOREIGN KEY (id_producto) REFERENCES producto (id_producto),
    CONSTRAINT ck_detalle_valores CHECK (cantidad > 0 AND precio_unit > 0)
);

CREATE TABLE historial_precio (
    id_historial     INT GENERATED BY DEFAULT AS IDENTITY,
    id_producto      INT NOT NULL,
    precio_det_ant   INT NOT NULL,
    precio_det_nuevo INT NOT NULL,
    precio_may_ant   INT NOT NULL,
    precio_may_nuevo INT NOT NULL,
    fecha_cambio     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    motivo           VARCHAR(100) NOT NULL,
    CONSTRAINT pk_historial_precio PRIMARY KEY (id_historial),
    CONSTRAINT fk_historial_producto FOREIGN KEY (id_producto) REFERENCES producto (id_producto) ON DELETE CASCADE
);

-- En PostgreSQL las FK no crean indice automaticamente (en MySQL si).
-- Se crean para mantener el mismo comportamiento en los JOIN.
CREATE INDEX idx_fk_producto_categoria ON producto (id_categoria);
CREATE INDEX idx_fk_producto_marca     ON producto (id_marca);
CREATE INDEX idx_fk_producto_proveedor ON producto (id_proveedor);
CREATE INDEX idx_fk_cliente_tipo       ON cliente (id_tipo_cliente);
CREATE INDEX idx_fk_venta_cliente      ON venta (id_cliente);
CREATE INDEX idx_fk_venta_empleado     ON venta (id_empleado);
CREATE INDEX idx_fk_detalle_venta      ON detalle_venta (id_venta);
CREATE INDEX idx_fk_detalle_producto   ON detalle_venta (id_producto);
CREATE INDEX idx_fk_historial_producto ON historial_precio (id_producto);

-- ---------------------------------------------------------------------
-- Seguridad (Supabase): RLS activado. La API publica (rol anon) solo
-- puede LEER; toda escritura pasa por las funciones del script 08.
-- ---------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['categoria','marca','proveedor','producto','stock','tipo_cliente',
                           'cliente','empleado','ticket','venta','detalle_venta','historial_precio']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY lectura_publica ON %I FOR SELECT TO anon, authenticated USING (true)', t);
  END LOOP;
END $$;
